const TAU = Math.PI * 2;
const cx = api.w / 2, cy = api.h / 2;
const nb = Math.max(1, Math.round(p.beams));

// faint ambient halo, breathes once per loop
const breathe = 0.5 + 0.5 * Math.sin(TAU * api.t);
api.circle(cx, cy, p.bloom * 1.3 + 0.6 * breathe, 3, 0.10 * p.intensity);

for (let b = 0; b < nb; b++) {
  const a = TAU * (api.t + b / nb);
  const sx = Math.sin(a), depth = Math.cos(a);
  const side = Math.abs(sx);
  if (side > 0.05) {
    const dir = sx >= 0 ? 1 : -1;
    // foreshortened length, but never a bare stub: keeps a visible cone at all angles
    const len = (0.30 + 0.70 * side) * p.reach * api.w * 0.62;
    const steps = Math.max(3, Math.round(len));
    // the cone tilts up/down as it swings, so the frames are clearly different poses
    const tilt = depth * p.taper * 2.2;
    for (let s = 1; s <= steps; s++) {
      const f = s / steps;
      const x = Math.round(cx + dir * f * len);
      // wedge: narrow at the lamp, flaring wide at the far end
      const hh = p.taper * (0.9 + f * 4.2);
      const axis = cy + tilt * f;
      const fall = 1 - f * 0.72;
      const base = fall * fall * (0.45 + 0.55 * side) * p.intensity;
      // soft outer wedge
      const ho = Math.max(1, Math.round(hh * 2));
      const ao = 0.26 * base;
      if (ao > 0.02) api.rect(x, Math.round(axis - hh), 1, ho, 3, ao);
      // mid wedge
      const hm = Math.max(1, Math.round(hh * 1.1));
      const am = 0.40 * base;
      if (am > 0.02) api.rect(x, Math.round(axis - hh * 0.55), 1, hm, 2, am);
      // brighter inner wedge
      const hi = Math.max(1, Math.round(hh * 0.55));
      const ai = 0.55 * base;
      if (ai > 0.03) api.rect(x, Math.round(axis - hh * 0.28), 1, hi, 1, ai);
      // hard hot core line down the axis, fades out fastest
      const ac = 0.9 * fall * fall * fall * (0.5 + 0.5 * side) * p.intensity;
      if (ac > 0.05) api.px(x, Math.round(axis), f < 0.45 ? 0 : 1, ac);
    }
  }
  // head-on flare: beam swinging toward the viewer blooms the lamp
  const face = (1 - depth) / 2;
  const bl = face * face * face;
  if (bl > 0.02) {
    api.circle(cx, cy, p.bloom * (1.0 + 2.1 * bl), 3, 0.16 * bl * p.intensity);
    api.circle(cx, cy, p.bloom * (0.55 + 1.2 * bl), 2, 0.32 * bl * p.intensity);
    api.circle(cx, cy, p.bloom * (0.24 + 0.6 * bl), 1, 0.58 * bl * p.intensity);
    // short vertical glare spike, sells a lamp pointed at you
    const sp = Math.round(p.bloom * (0.6 + 1.4 * bl));
    for (let k = 1; k <= sp; k++) {
      const av = 0.5 * bl * p.intensity * (1 - k / (sp + 1));
      if (av > 0.04) {
        api.px(Math.round(cx), Math.round(cy) - k, 1, av);
        api.px(Math.round(cx), Math.round(cy) + k, 1, av);
      }
    }
  }
}

// the lamp itself: small, hard, always the brightest thing on the sheet
api.circle(cx, cy, 2.2, 2, 0.5 * p.intensity);
api.circle(cx, cy, 1.2, 0, 0.9 * p.intensity);
api.px(Math.round(cx), Math.round(cy), 0, p.intensity);
api.px(Math.round(cx) - 1, Math.round(cy), 0, 0.75 * p.intensity);
api.px(Math.round(cx) + 1, Math.round(cy), 0, 0.75 * p.intensity);
